import type { MappingVersion, VariantMapping } from "../types";

/** The version record as published. */
export const forearmMappingVersionV1: MappingVersion = {"key":"forearm_mappings_v1","state":"published","publishedAt":"2026-10-16","methodNotes":"Each catalog exercise the forearm atlas maps has one default variant (cat-<id>) with its execution spelled out: organization, forearm orientation, wrist position, grip, straps, laterality, measure, deliberate hold, and an elbow angle only where the exercise defines one. Each mapping names one muscle, one joint action, a relationship (direct, contributing, stabilizer, incidental) and a muscle mode (dynamic or isometric) separately, so one set can be dynamic elbow flexion and isometric wrist stabilization at once. Mappings are by catalog id; no name matching. A mapping is reviewed when the muscle's action is sourced (anatomy tables S4, S7, S8, the arm reference M8) and the relationship is explained in its rationale; EMG sources (S2, S3, M1, M2, M5-M7) are cited only for what they measured. Everything else stays draft and is shown as pending review, never counted. FDS and FDP are always credited together as shared: nothing in an ordinary grip separates them. Grip during rows, pulldowns, pull-ups, deadlifts, shrugs and hangs is incidental and is not earned by a set logged with straps. No percentage splits between muscles, no mapping credits every forearm muscle, the hand's own muscles are not credited to the forearm, and a broad 'forearms' tag on an unmapped exercise stays region-level."};

